/*!
 * water-reveal.js — Effet "révélation par l'eau" au curseur (header/hero)
 * Le curseur mouille la surface et révèle une image cachée le long de son
 * passage (la zone sèche en ~0,4 s), avec une vraie équation d'onde GPU :
 * anneaux qui se propagent, réfraction subtile, reflets. Zéro dépendance.
 * Physique de base adaptée de WebGL-Fluid-Simulation (Pavel Dobryakov, MIT).
 *
 * USAGE (vanilla) :
 *   <div id="hero" style="position:relative">
 *     <img src="photo-de-fond.jpg" ...>            <!-- couche visible -->
 *     <canvas id="water" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></canvas>
 *   </div>
 *   <script type="module">
 *     import { initWaterReveal } from './water-reveal.js'
 *     initWaterReveal({ canvas: document.getElementById('water'),
 *                       container: document.getElementById('hero'),
 *                       imageUrl: '/photo-revelee.jpg' })
 *   <\/script>
 *
 * IMPORTANT (CORS) : imageUrl doit être same-origin ou servie avec
 * Access-Control-Allow-Origin, sinon WebGL refuse la texture.
 * Options : voir DEFAULTS ci-dessous (tous surchargables).
 */
